  ["OneIsland_KindleRoad_Text_KiaRematchIntro"] = "KIA: Meu irmão e eu somos uma\\ncombinação incrível!\\pNão vamos perder desta vez!",
  ["OneIsland_KindleRoad_Text_MariaRematchIntro"] = "O tempo está maravilhoso!\\nVou tentar não estragá-lo.",
  ["OneIsland_KindleRoad_Text_MikRematchIntro"] = "MIK: Junto com a KIA, a gente\\nnão teme nada!\\pVamos provar pra você desta vez!",
  ["OneIsland_KindleRoad_Text_SharonRematchIntro"] = "Você vai me ajudar com o meu\\ntreinamento de novo?",
  ["OneIsland_KindleRoad_Text_SheaRematchIntro"] = "Todo dia de manhã, antes do café,\\neu nado em volta desta ilha…\\lTrês vezes!",
  ["OneIsland_KindleRoad_Text_TanyaRematchIntro"] = "Não perdemos um único dia de\\ntreinamento ainda!",
  ["OneIsland_KindleRoad_Text_TommyRematchIntro"] = "Espera! Espera um pouco! Tenho\\ncerteza que fisguei um dos grandes!",
  ["OneIsland_TreasureBeach_Text_AmaraRematchIntro"] = "Deitado, balançando nas ondas…\\nNem noto o tempo passar…",
  ["PalletTown_Text_HmmIsThatRight"] = "Hmm…\\nÉ isso mesmo…",
  ["PalletTown_Text_LookCopiedTrainerTipsSign"] = "Olha, olha!\\pEu copiei o que dizia em uma\\ndaquelas placas de DICAS PARA\\lTREINADORES!",
