  ["Route11_Text_BraxtonRematchIntro"] = "Oi!\\pMas cuidado!\\nAinda estou passando alguns cabos!",
  ["Route11_Text_DarianRematchIntro"] = "Eu nunca venci antes…\\pTalvez eu esteja destinado a\\ncontinuar assim…",
  ["Route11_Text_DaveRematchIntro"] = "Criei meus POKéMON com cuidado.\\nEles devem estar prontos agora!\\lDesta vez, eles vão vencer.",
  ["Route11_Text_DillonRematchIntro"] = "Me tornei TREINADOR há algum tempo.\\nMas acho que consigo vencer.",
