  ["Route123_BerryMastersHouse_Text_YoureDeservingOfBerry"] = "?Ïè ÊçîòÁ?+Ñ ù?ºÛÈñ\\p?Ïè ÓÉÁ?=Â& ÂÚËÏÁ èß?\\nÂòÚËÔÂÑ Êçî& Ô?ÛÛ\\lÔÏÛ Ë?û ?Ë?Û Èñç??\\pÊîàó Êçî& ?ÌÛ À?ùÂ!",
  ["Route12_Text_AndrewRematchIntro"] = "Qual é a boa?\\pVocê nunca vai descobrir a menos\\nque me vença!",
  ["Route12_Text_ChipRematchIntro"] = "Você finalmente chegou.\\nPescar é um jogo de paciência.",
  ["Route12_Text_ElliotRematchIntro"] = "Eu amo pescar, não me entenda mal.\\nMas eu queria ter mais trabalho…\\l… É difícil largar a pesca!",
  ["Route12_Text_GiaRematchIntro"] = "GIA: Ei, JES…\\nJá tô esperando há muito tempo.\\pSe a gente vencer hoje, eu me caso\\ncom você!",
  ["Route12_Text_HankRematchIntro"] = "O MANÍACO POR PESCA contra {o_a}\\n{TREINADOR_TREINADORA} POKéMON!\\lMais uma rodada, lutem!",
  ["Route12_Text_JesRematchIntro"] = "JES: Hoje vou vencer e pedir minha\\nGIA em casamento.",
  ["Route12_Text_JustinRematchIntro"] = "Ainda não consegui encontrar uma\\nPEDRA DA LUA…\\lVocê encontrou alguma?",
  ["Route12_Text_LucaRematchIntro"] = "Eletricidade sempre foi minha\\nespecialidade.\\pMas eu não entendo nada de\\nPOKéMON do mar.",
  ["Route12_Text_NedRematchIntro"] = "É isso aí!\\nFisguei alguma coisa aqui!\\lE-essa pode ser uma grande captura!",
  ["Route13_Text_AlmaRematchIntro"] = "Gastei todas as minhas economias\\ne comprei mais CARBOIDRATOS.",
  ["Route13_Text_GwenRematchIntro"] = "Meus POKéMON fofos e crescidos\\nquerem reencontrar você.",
  ["Route13_Text_JaredRematchIntro"] = "Tá olhando o quê?",
  ["Route13_Text_LolaRematchIntro"] = "Ah, você voltou?\\pClaro, eu brinco de novo com você,\\nqueridinh{o_a}.",
  ["Route13_Text_PerryRematchIntro"] = "Desta vez eu não vou perder.\\nO vento está soprando a meu favor!",
  ["Route13_Text_RobertRematchIntro"] = "Sempre uso os POKéMON pássaro.\\nMe dediquei totalmente a eles.",
  ["Route13_Text_SebastianRematchIntro"] = "Meus POKéMON pássaro se lembram\\nde você!",
  ["Route13_Text_SheilaRematchIntro"] = "Não dá pra você esquecer que\\njá batalhou comigo?",
  ["Route13_Text_SusieRematchIntro"] = "Quero ser a melhor TREINADORA\\nenquanto ainda sou criança!",
  ["Route13_Text_ValerieRematchIntro"] = "Uau!\\pVocê conseguiu mais INSÍGNIAS\\nlegais!",
  ["Route14_Text_BeckRematchIntro"] = "Você está usando MTs nos seus\\nPOKéMON?\\pSó ficar guardando elas não adianta\\nnada.",
  ["Route14_Text_BennyRematchIntro"] = "Não curto muito isso, mas tudo bem.\\nVamos lá!",
  ["Route14_Text_CarterRematchIntro"] = "Usei MTs para ensinar movimentos\\nbons aos meus POKéMON.",
  ["Route14_Text_DonaldRematchIntro"] = "A lenda das miragens aladas…\\nVocê já ouviu falar, né?",
  ["Route14_Text_GeraldRematchIntro"] = "A gente tá andando de moto por aqui\\npor causa dos espaços abertos.",
  ["Route14_Text_IsaacRematchIntro"] = "Você tá aqui de novo, hein?\\nCala a boca e vamos batalhar.",
  ["Route14_Text_JanRematchIntro"] = "JAN: KIRI, lá vamos nós!\\nDesta vez, vamos vencer com certeza!",
  ["Route14_Text_KiriRematchIntro"] = "KIRI: JAN, tomara que a gente\\nvença hoje.",
  ["Route14_Text_LukasRematchIntro"] = "Ei!\\nEu me lembro de você!\\pBora, bora!\\nVamos, vamos, vamos!",
  ["Route14_Text_MalikRematchIntro"] = "Batalha de POKéMON, né?\\nLegal! Vamos batalhar!",
  ["Route14_Text_MarlonRematchIntro"] = "Você ensinou seus POKéMON pássaro\\na VOAR?\\pCom isso, você vai poder voar alto\\npelo céu! Experimente.",
  ["Route14_Text_MitchRematchIntro"] = "Meus POKéMON pássaro devem estar\\nprontos para a batalha desta vez.",
  ["Route15_Text_AlexRematchIntro"] = "Passa todo o seu dinheiro quando\\nvocê perder pra mim, garot{o_a}!",
  ["Route15_Text_BeckyRematchIntro"] = "Você parece ser gentil, então acho\\nque posso te vencer.\\pVou tentar mais uma vez!",
  ["Route15_Text_CeliaRematchIntro"] = "O que é legal e está na moda?\\nTrocar POKéMON, é claro!",
  ["Route15_Text_ChesterRematchIntro"] = "Hmm? Meus pássaros estão tremendo!\\pEspera… você não é {o_a} {TREINADOR_TREINADORA}\\ndaquela vez?",
  ["Route15_Text_EdwinRematchIntro"] = "Quando eu assobio, os POKéMON\\npássaro se juntam ao meu redor.\\pEles são incrivelmente fofos!",
  ["Route15_Text_ErnestRematchIntro"] = "Ei, garot{o_a}! Vamos nessa!\\nConsegui estes POKéMON de um\\lperdedor qualquer!",
  ["Route15_Text_GraceRematchIntro"] = "Ah, que gracinha!\\nParece até um POKéMON fofinho!\\lAgora eu lembrei de você!",
  ["Route15_Text_KindraRematchIntro"] = "Vou continuar batalhando com os\\nPOKéMON que consegui em trocas.",
  ["Route15_Text_MyaRematchIntro"] = "MYA: Oi, a gente vive se\\nencontrando, não é?\\pAjuda a treinar meu irmãozinho\\nde novo?",
  ["Route15_Text_OliviaRematchIntro"] = "Crio POKéMON para me proteger,\\nporque moro sozinha.\\pIsso não mudou.",
  ["Route15_Text_RonRematchIntro"] = "RON: Minha irmã ficou mais forte…",
  ["Route15_Text_YazminRematchIntro"] = "Quer brincar com meus POKéMON\\nde novo?",
  ["Route16_Text_CamronRematchIntro"] = "Tô com fome e de mau humor!\\nPreciso de um saco de pancadas!",
  ["Route16_Text_HideoRematchIntro"] = "Ei, espera um segundo!\\nNão me chame e depois saia correndo!",
  ["Route16_Text_JedRematchIntro"] = "JED: Veio ver o nosso amor,\\nque não conhece limites?",
  ["Route16_Text_KojiRematchIntro"] = "Bela BIKE!\\nEntrega ela logo!",
  ["Route16_Text_LaoRematchIntro"] = "O que você quer?",
  ["Route16_Text_LeaRematchIntro"] = "LEA: Às vezes, a intensidade do\\nnosso amor me assusta.",
  ["Route16_Text_LukeRematchIntro"] = "Apareça e venha brincar, ratinh{o_a}.\\nVou cuidar bem de você!",
  ["Route16_Text_RubenRematchIntro"] = "Ei, você aí!\\nVamos nos divertir muito!",
  ["Route17_Text_BillyRematchIntro"] = "Nós somos MOTOQUEIROS!\\nA gente manda nas estradas, cara!",
  ["Route17_Text_CoreyRematchIntro"] = "Seja {um_uma} rebelde!",
  ["Route17_Text_IsaiahRematchIntro"] = "Tenho muito orgulho do meu corpo,\\ngarot{o_a}. Vamos nessa!",
  ["Route17_Text_JamalRematchIntro"] = "Gaaah! Preciso mesmo me exercitar\\ne perder essa gordura!",
  ["Route17_Text_JaxonRematchIntro"] = "É verdade, que BICICLETA legal!\\nComo ela corre?",
  ["Route17_Text_NikolasRematchIntro"] = "VOLTORB vai eletrizar você pra\\nvaler hoje!",
  ["Route17_Text_RaulRematchIntro"] = "Eu te disse, não dá pra ficar ric{o_a}\\nrápido batalhando com crianças.",
  ["Route17_Text_VirgilRematchIntro"] = "Tá passeando?",
  ["Route17_Text_WilliamRematchIntro"] = "Cai fora, garot{o_a}!\\nTô exausto!",
  ["Route17_Text_ZeekRematchIntro"] = "Subi o nível do meu POKéMON, mas\\nele não evolui de jeito nenhum.\\lPor quê?",
  ["Route18_Text_JacobRematchIntro"] = "Eu te avisei antes, este é o\\nmeu território!\\pNão quero você por aqui.",
  ["Route18_Text_RamiroRematchIntro"] = "Cucurucucuu!\\nMeu canto de pássaro tá melhorando?",
  ["Route18_Text_WiltonRematchIntro"] = "Tenho olhado em cada área de grama\\nà procura de novos POKéMON.\\pMas nem sempre é fácil…",
  ["Route19_Text_AliceRematchIntro"] = "Nadar é ótimo!\\nQueimaduras de sol não!",
  ["Route19_Text_AnyaRematchIntro"] = "Você sempre pode montar no seu\\nPOKéMON…\\pParece tão relaxante.\\nPosso ficar com ele se eu vencer?",
  ["Route19_Text_AxleRematchIntro"] = "Estas águas são traiçoeiras!\\nVocê não deveria voltar aqui!",
  ["Route19_Text_ConnieRematchIntro"] = "Nadei até aqui com meus amigos…\\nTô cansada…\\pA gente tem mesmo que batalhar\\nde novo?",
  ["Route19_Text_DavidRematchIntro"] = "Tentei mergulhar à procura de\\nPOKéMON de novo, mas não deu\\lem nada como antes.",
  ["Route19_Text_DouglasRematchIntro"] = "O que há além do horizonte?\\nVocê já viu?",
  ["Route19_Text_LiaRematchIntro"] = "LIA: Você sabe que meu irmão acabou\\nde se tornar um TREINADOR, né?\\pQuero que ele melhore, então preciso\\nda sua ajuda de novo.",
  ["Route19_Text_LucRematchIntro"] = "LUC: Minha irmã me ensinou tudo\\nsobre POKéMON.\\pSerá que estou melhor?",
  ["Route19_Text_MatthewRematchIntro"] = "Adoro nadar!\\nAcho que você é do tipo que surfa.",
  ["Route19_Text_ReeceRematchIntro"] = "Espera! Vai devagar! E se você\\ntiver um ataque do coração?",
  ["Route19_Text_RichardRematchIntro"] = "Tô quase aquecido pra dar um\\nmergulho.",
  ["Route19_Text_TonyRematchIntro"] = "Olho pro mar pra esquecer todas\\nas coisas ruins que aconteceram.\\p… Tipo perder pra você da última\\nvez!",
  ["Route20_Text_BarryRematchIntro"] = "A água é rasa por aqui.\\nTem muita gente nadando.",
  ["Route20_Text_DarrinRematchIntro"] = "Por que você está montad{o_a} em um\\nPOKéMON?\\pAinda não aprendeu a nadar?",
  ["Route20_Text_DeanRematchIntro"] = "Dá uma olhada no meu físico!\\pTô mais sarado do que nunca!",
  ["Route20_Text_IreneRematchIntro"] = "Você também estava de férias?",
  ["Route20_Text_MelissaRematchIntro"] = "CINNABAR, no oeste, tem um\\nLABORATÓRIO para POKéMON.\\pMeu papai trabalha lá.",
  ["Route20_Text_MissyRematchIntro"] = "Nadei da ILHA DE CINNABAR até aqui.\\nNão foi nada fácil, como eu disse.",
  ["Route20_Text_NoraRematchIntro"] = "Meu namorado me deu pérolas grandes.\\nE elas cresceram ainda mais!",
  ["Route20_Text_RogerRematchIntro"] = "Vim montado no meu POKéMON pássaro\\naté aqui.",
  ["Route20_Text_ShirleyRematchIntro"] = "Você tá com inveja de eu estar\\nde férias nas ILHAS ESPUMA?",
  ["Route20_Text_TiffanyRematchIntro"] = "Adoro flutuar com os peixes aqui\\nentre as ondas.",
  ["Route21_North_Text_CueBallRematchIntro"] = "Ê;Âó Èù?à\\nÊÙ??Œ?",
  ["Route21_North_Text_IanRematchIntro"] = "IAN: Minha irmã é muito mole.\\nMe ajuda a dar um jeito nela!",
  ["Route21_North_Text_LilRematchIntro"] = "LIL: Hein? Outra batalha?\\nIAN, não consegue sozinho?",
  ["Route21_North_Text_RonaldRematchIntro"] = "Você quer saber se os peixes estão\\nmordendo?",
  ["Route21_North_Text_SpencerRematchIntro"] = "O mar limpa meu corpo e minha alma!",
  ["Route21_North_Text_WadeRematchIntro"] = "Fiz uma grande pescaria de novo!\\nQuer mais uma rodada?",
  ["Route21_South_Text_ClaudeRematchIntro"] = "Ei, para com isso já!\\nVocê sempre espanta os peixes!",
  ["Route21_South_Text_JackRematchIntro"] = "Peguei meus POKéMON no mar.\\nE é nele que eu treino eles.",
  ["Route21_South_Text_JeromeRematchIntro"] = "Neste momento, estou em outra\\ncompetição de triatlo!",
  ["Route21_South_Text_NolanRematchIntro"] = "Fica comigo até eu fisgar algo.",
  ["Route21_South_Text_RolandRematchIntro"] = "Ahh!\\nSinta o sol e o vento!",
  ["Route24_Text_AliRematchIntro"] = "Aquela vez que batalhamos…\\pMesmo eu sendo o segunda da\\nfila, eu era a melhor, não era?",
  ["Route24_Text_CaleRematchIntro"] = "O pessoal chama este lugar de\\nPONTE DA PEPITA!\\pVocê já nos venceu, então não pode\\naceitar o desafio…\\p… Mas, sinta-se à vontade pra\\nbatalhar com a gente de novo.",
  ["Route24_Text_EthanRematchIntro"] = "Tudo bem!\\nVou te esmagar!",
  ["Route24_Text_ReliRematchIntro"] = "Você sempre parece tão ocupad{o_a}…\\nNão tá ficando cansad{o_a}?",
  ["Route24_Text_ShaneRematchIntro"] = "Vi o seu feito aqui do meio da\\ngrama!",
  ["Route24_Text_TimmyRematchIntro"] = "Você deve amar mesmo vir até a\\nPONTE DA PEPITA.",
  ["Route25_Text_ChadRematchIntro"] = "Eu tive esse pressentimento…\\pSabia que batalharia com você de\\nnovo!",
  ["Route25_Text_DanRematchIntro"] = "Meu pai me levou a uma festa\\nótima no SANTA ANA na CIDADE\\lDE VERMILION.",
  ["Route25_Text_FlintRematchIntro"] = "Sou um cara descolado.\\nTenho uma namorada!\\pDesta vez, vou mostrar pra ela\\ncomo eu sou legal com certeza!",
  ["Route25_Text_FranklinRematchIntro"] = "Acabei de treinar no MONTE LUA,\\nmas ainda tenho energia de sobra!",
  ["Route25_Text_HaleyRematchIntro"] = "Minha amiga tem muitos POKéMON\\nfofos. Tô morrendo de inveja!",
  ["Route25_Text_JoeyRematchIntro"] = "Não vou perder enquanto eu\\nestiver aqui!",
  ["Route25_Text_KelseyRematchIntro"] = "Oi!\\nMeu namorado é o máximo!\\lTô em ótima forma hoje!",
  ["Route25_Text_NobRematchIntro"] = "Um POKéMANÍACO vive no cabo.\\nJá viu a coleção dele?",
  ["Route25_Text_WayneRematchIntro"] = "Você vai ver o BILL de novo?\\nPrimeiro, vamos batalhar!",
  ["Route3_Text_BenRematchIntro"] = "Oi! Eu gosto de shorts!\\nSão confortáveis e fáceis de usar!\\pVocê também devia estar usando\\nshorts!",
  ["Route3_Text_CalvinRematchIntro"] = "Ei! Qual é o seu problema?\\nVocê ainda não tá usando shorts!",
  ["Route3_Text_ColtonRematchIntro"] = "Ei!\\nEu te vi na FLORESTA DE VIRIDIAN!",
  ["Route3_Text_GregRematchIntro"] = "Você é {um_uma} {TREINADOR_TREINADORA}, não é?\\nEntão vamos nessa agora mesmo!",
  ["Route3_Text_JamesRematchIntro"] = "Vou batalhar usando os POKéMON \\nque comecei a criar.",
  ["Route3_Text_JaniceRematchIntro"] = "Com licença!\\nVocê continua olhando pra mim, né?",
  ["Route3_Text_RobinRematchIntro"] = "Ai!\\nFoi você que me empurrou?",
  ["Route3_Text_SallyRematchIntro"] = "O jeito que você me olhou…\\nMe deixa tão intrigada!",
  ["Route4_Text_CrissyRematchIntro"] = "Sempre capturo POKéMON cogumelo\\nno MONTE LUA.",
  ["Route6_Text_ElijahRematchIntro"] = "Ei, quanto tempo!\\nVocê ficou mais forte?",
  ["Route6_Text_IsabelleRematchIntro"] = "Eu?\\nTá bom. Vou batalhar só dessa vez.",
  ["Route6_Text_JeffRematchIntro"] = "Hã?\\nVocê quer batalhar comigo de novo?",
  ["Route6_Text_KeigoRematchIntro"] = "Tô tentando encontrar algo bom que\\nnão seja um POKéMON INSETO, mas…",
  ["Route6_Text_NancyRematchIntro"] = "Com licença! Eu não disse que\\nisso é uma conversa particular?\\pVocê não devia estar escutando,\\n{seu_sua} mal-educad{o_a}!",
  ["Route6_Text_RickyRematchIntro"] = "Ah! Você é {o_a} garot{o_a} intrometid{o_a} que\\nestava escutando a nossa conversa!",
  ["Route8_Text_AidanRematchIntro"] = "Você é {bom_boa} em POKéMON, mas e a\\nsua nota em química, como vai?",
  ["Route8_Text_AndreaRematchIntro"] = "MEOWTH e PERSIAN são tão fofinhos,\\nmiau, miau, miau!",
  ["Route8_Text_AnneRematchIntro"] = "ANNE: Nosso poder de gêmeas\\naumentou ainda mais!",
  ["Route8_Text_EliRematchIntro"] = "ELI: Nosso poder de gêmeas ficou\\nainda melhor!",
  ["Route8_Text_GlennRematchIntro"] = "Você precisa de estratégia para\\nvencer batalhas.\\pTá seguindo o meu conselho?",
  ["Route8_Text_JarenRematchIntro"] = "Tá bom, garot{o_a}!\\nNão espere misericórdia desta vez!",
  ["Route8_Text_JuliaRematchIntro"] = "Qual é o POKéMON fofo, redondo\\ne macio?\\pVocê já sabe, não sabe?",
  ["Route8_Text_LeslieRematchIntro"] = "A escola é divertida, mas eu ainda\\nacho que POKéMON também são.",
  ["Route8_Text_MeganRematchIntro"] = "A gente pode até parecer bobo\\nparado aqui assim, mas eu ainda\\lposso batalhar.",
  ["Route8_Text_PaigeRematchIntro"] = "Eu colecionei vários NIDORAN.\\nNão quero que eles evoluam, mas…",
  ["Route8_Text_RicardoRematchIntro"] = "Minha moto ainda tá com problema,\\ncara.",
  ["Route8_Text_RichRematchIntro"] = "Sou um cara que vive falando e\\njogando! Tô numa maré de vitórias!",
  ["Route8_Text_StanRematchIntro"] = "Tudo bem!\\nVamos jogar outra partida!",
  ["Route9_Text_AlanRematchIntro"] = "Hahahaha!\\nDesta vez eu vou vencer!",
  ["Route9_Text_AliciaRematchIntro"] = "Vamos batalhar de novo?\\nDesta vez, você é {meu_minha}!",
  ["Route9_Text_BrentRematchIntro"] = "Eu acordava cedo todo dia pra\\ntreinar meus POKéMON desde os\\lcasulos!",
  ["Route9_Text_BriceRematchIntro"] = "Hahaha!\\nForte como sempre!",
  ["Route9_Text_CaitlinRematchIntro"] = "Nem pensa em me subestimar hoje!\\nAgora é pra valer!",
  ["Route9_Text_ChrisRematchIntro"] = "Não esqueci que você estava com\\naqueles POKéMON bonitões.",
  ["Route9_Text_ConnerRematchIntro"] = "Vão lá e vençam, meus super\\nPOKéMON INSETO!",
  ["Route9_Text_DrewRematchIntro"] = "Vou passar pelo TÚNEL DE ROCHA\\npara chegar a LAVENDER…\\pMas todo mundo fica me parando\\npelo caminho…",
  ["Route9_Text_JeremyRematchIntro"] = "Bwahaha!\\nÓtimo! Eu tava entediado de novo!",
  ["STRINGID_123POOF"] = "\252\008\0321, \252\008\0152 e\252\008\015... \252\008\015... \252\008\015... \252\008\015\252\016\049\000Puf!\\p",
