  ["STRINGID_MIRRORMOVEFAILED"] = "O ATAQUE ESPELHADO falhou!",
  ["STRINGID_MONHEARINGFLUTEAWOKE"] = "O POKéMON acordou ao ouvir a\\nFLAUTA!",
  ["STRINGID_MONTOOSCAREDTOMOVE"] = "{B_ATK_NAME_WITH_PREFIX} está tão assustado\\nque não consegue de mover!",
  ["STRINGID_NATUREPOWERTURNEDINTO"] = "ADAPTAÇÃO se transformou em\\n{B_CURRENT_MOVE}!",
  ["STRINGID_NOPPLEFT"] = "Não restam PP para este\\nmovimento!\\p",
  ["STRINGID_NORUNNINGFROMTRAINERS"] = "Você não pode fugir de uma\\nbatalha contra um TREINADOR!\\p",
  ["STRINGID_NOTVERYEFFECTIVE"] = "Não é muito eficaz…",
  ["STRINGID_OAKPLAYERLOST"] = "CARVALHO: Hm…\\nQue decepção…\\pSe você vencer, ganhará dinheiro\\ne o seu POKéMON experiência.\\pMas se perder, {B_PLAYER_NAME}, terá\\nque pagar uma quantia…\\pBem, como é a sua primeira vez e\\nvocê não sabia, pagarei por você.\\pMas as coisas não serão assim\\nquando sair por aquelas portas.\\pÉ por isso que deve fortalecer seu\\nPOKéMON batalhando contra POKéMON\\lselvagens.\\p",
  ["STRINGID_OAKPLAYERWON"] = "CARVALHO: Hm! Excelente!\\pSe você vencer, ganhará dinheiro\\ne o seu POKéMON experiência.\\pBatalhe contra outros TREINADORES\\ne torne o seu POKéMON mais forte!\\p",
