  ["SevenIsland_SevaultCanyon_Entrance_Text_EveRematchIntro"] = "EVE: Vou fazer dupla com o JON\\ne batalhar juntos de novo.",
  ["SevenIsland_SevaultCanyon_Entrance_Text_JonRematchIntro"] = "JON: Quando estou com a EVE,\\nsinto que nunca perderemos,\\lnunca mesmo.",
  ["SevenIsland_SevaultCanyon_Entrance_Text_MadelineRematchIntro"] = "Eu não perdoo quem maltrata\\nPOKéMON!",
  ["SevenIsland_SevaultCanyon_Entrance_Text_MasonRematchIntro"] = "Olá! Você é membro do meu\\nfã-clube, não é mesmo?",
  ["SevenIsland_SevaultCanyon_Entrance_Text_MiahRematchIntro"] = "Kyahaha!\\pVoltar não vai mudar nada.\\nVou te derrotar num piscar de olhos!",
  ["SevenIsland_SevaultCanyon_Entrance_Text_NicolasRematchIntro"] = "Esta ilha é grande demais…\\nPatrulhar este lugar é um saco…",
  ["SevenIsland_SevaultCanyon_Text_CyndyRematchIntro"] = "Vamos batalhar de novo.\\nEstou em plena forma!",
  ["SevenIsland_SevaultCanyon_Text_EvanRematchIntro"] = "Não importa se você por acaso\\ntem os POKéMON mais fortes…\\pNão significa nada se você não\\nsouber usá-los direito!",
  ["SevenIsland_SevaultCanyon_Text_JacksonRematchIntro"] = "Eu trabalho para proteger o meio\\nambiente.\\pEm troca, a natureza me protege!",
  ["SevenIsland_SevaultCanyon_Text_KatelynRematchIntro"] = "Toda vez que a gente se vê, você\\nestá com esses calçados estilosos.",
  ["SevenIsland_SevaultCanyon_Text_LeroyRematchIntro"] = "Você deve ter ficado mais forte.\\pDeixa eu batalhar com você,\\npor favor!",
  ["SevenIsland_SevaultCanyon_Text_LexRematchIntro"] = "LEX: Minha querida NYA, juntos\\nvenceremos com certeza!",
  ["SevenIsland_SevaultCanyon_Text_MichelleRematchIntro"] = "Recebi a melhor educação possível\\npara me tornar assim tão forte.\\pNão vou perder desta vez.\\nCom certeza não!",
  ["SevenIsland_SevaultCanyon_Text_NyaRematchIntro"] = "NYA: Não vou decepcionar meu\\nmentor LEX! Nós vamos vencer!",
  ["SevenIsland_TanobyRuins_Text_BenjaminRematchIntro"] = "Dizem que um POKéMON místico\\ndorme aqui dentro.",
  ["SevenIsland_TanobyRuins_Text_BrandonRematchIntro"] = "Você descobriu alguma coisa sobre\\nesta câmara de pedra?",
  ["SevenIsland_TanobyRuins_Text_CliffordRematchIntro"] = "Hoje, além da nossa aula, viemos\\nver a câmara novamente.",
  ["SevenIsland_TanobyRuins_Text_EdnaRematchIntro"] = "Meu professor está me ensinando a\\npintar um pouco mais.",
  ["SevenIsland_TrainerTower_Text_DarioRematchIntro"] = "Senti sua aproximação.",
  ["SevenIsland_TrainerTower_Text_RodetteRematchIntro"] = "Em algum lugar desta ilha, POKéMON\\npeculiares estão dormindo.",
  ["SixIsland_GreenPath_Text_JaclynRematchIntro"] = "… Hã?\\pEu penso na minha casa, mas\\nsempre me TELEPORTO pra cá!",
  ["SixIsland_OutcastIsland_Text_AvaRematchIntro"] = "AVA: Vamos ter outra batalha\\nmarinha de dois contra dois hoje!",
  ["SixIsland_OutcastIsland_Text_GebRematchIntro"] = "GEB: Minha irmã e eu estamos muito\\nmais fortes do que antes!",
  ["SixIsland_OutcastIsland_Text_MymoRematchIntro"] = "Oof… Oof…\\pNadei do porto da SEIS ILHAS\\naté aqui direto, de novo.",
  ["SixIsland_OutcastIsland_Text_NicoleRematchIntro"] = "Você sempre aparece enquanto\\nestou nadando.",
