  ["sFameCheckerFlavorTextPointers[12]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003LÍDER del GIMNASIO POKéMON\\nde PLATEADA: BROCK\\l¡Es fuerte como una roca!",
  ["sFameCheckerFlavorTextPointers[13]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003¡Creo en la gran resistencia de la\\nroca y en la determinación!\\p¡Por eso todos mis POKéMON son\\ndel tipo ROCA!",
  ["sFameCheckerFlavorTextPointers[14]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡No hay muchos ENTRENADORES\\nde POKéMON por aquí!\\p¡Todos parecen CAZABICHOS, salvo\\nBROCK, del GIMNASIO de PLATEADA!",
  ["sFameCheckerFlavorTextPointers[15]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003BROCK es, además de fuerte, guay.\\nTodos lo respetan y admiran mucho.\\pYo quiero ser LÍDER de GIMNASIO\\ncomo él.",
  ["sFameCheckerFlavorTextPointers[16]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Estoy buscando fósiles en las\\nentrañas del MT. MOON.\\pA veces me ayuda BROCK,\\ndel GIMNASIO de PLATEADA.",
  ["sFameCheckerFlavorTextPointers[17]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, BROCK\\ncasi nunca se ríe, ¡pero una vez\\lque empieza, no para!",
  ["sFameCheckerFlavorTextPointers[18]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003LÍDER del GIMNASIO POKéMON\\nde CELESTE: MISTY\\l¡La sirena distorsionada!",
  ["sFameCheckerFlavorTextPointers[19]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\005\252\001\002\252\003\003¡Mi táctica es la ofensiva total\\ncon los POKéMON del tipo AGUA!",
  ["sFameCheckerFlavorTextPointers[1]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Quería hacer una guía de todos\\nlos POKéMON del mundo...\\p¡Era mi sueño!",
  ["sFameCheckerFlavorTextPointers[20]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡MISTY es cada vez más fuerte!\\p¡No perderá con alguien como tú!",
  ["sFameCheckerFlavorTextPointers[21]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Por aquí hay muchos ENTRENADORES\\nfuertes y POKéMON del tipo AGUA.\\pDicen que MISTY, del GIMNASIO\\nde CELESTE, se entrena por aquí.",
  ["sFameCheckerFlavorTextPointers[22]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003En este cabo queda mucha gente.\\pMISTY, la LÍDER del GIMNASIO,\\nsuele venir por aquí.",
  ["sFameCheckerFlavorTextPointers[23]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, MISTY\\nadora a LORELEI, del ALTO MANDO.",
  ["sFameCheckerFlavorTextPointers[24]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003LÍDER del GIMNASIO POKéMON\\nde CARMÍN: LT. SURGE\\l¡El Rayo americano!",
  ["sFameCheckerFlavorTextPointers[25]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003¡Los POKéMON ELÉCTRICOS\\nme salvaron en combate!",
  ["sFameCheckerFlavorTextPointers[26]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡Cuando estaba en el ejército,\\nel LT. SURGE era muy estricto!",
  ["sFameCheckerFlavorTextPointers[27]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡El LT. SURGE siempre fue muy\\ncuidadoso en el ejército!",
  ["sFameCheckerFlavorTextPointers[28]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003LT. SURGE colocó cerraduras\\ndobles en el GIMNASIO.\\p¡Las puso por todos sitios!",
  ["sFameCheckerFlavorTextPointers[29]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, LT. SURGE\\nera piloto cuando vivía en Estados\\lUnidos.\\pY se valía de la electricidad\\ngenerada por sus POKéMON\\lpara poner en marcha su avión.",
  ["sFameCheckerFlavorTextPointers[2]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡El PROF. OAK es un experto\\nen POKéMON!\\p¡Es admirado por muchos de los\\nENTRENADORES POKéMON!",
  ["sFameCheckerFlavorTextPointers[30]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003LÍDER del GIMNASIO POKéMON\\nde AZULONA: ERIKA\\l¡Princesa amante de la Naturaleza!",
  ["sFameCheckerFlavorTextPointers[31]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\005\252\001\002\252\003\003Enseño el arte de las flores.\\nMis POKéMON son del tipo PLANTA.",
  ["sFameCheckerFlavorTextPointers[32]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡ERIKA, nuestra LÍDER, puede\\nparecer muy tranquila, pero es muy\\lhábil!",
  ["sFameCheckerFlavorTextPointers[33]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡En nuestro GIMNASIO sólo luchamos\\ncon POKéMON del tipo PLANTA!\\p¡Y también los usamos para hacer\\nadornos florales!",
  ["sFameCheckerFlavorTextPointers[34]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\005\252\001\002\252\003\003No coleccionaría POKéMON si\\nfueran feos.",
  ["sFameCheckerFlavorTextPointers[35]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, es fácil\\nver a ERIKA echándose una siesta\\len el GIMNASIO de AZULONA.",
  ["sFameCheckerFlavorTextPointers[36]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003LÍDER del GIMNASIO POKéMON\\nde FUCSIA: KOGA\\lEl venenoso maestro ninja.",
  ["sFameCheckerFlavorTextPointers[37]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003¡Adoro a mis temidos POKéMON\\ndel tipo VENENO!",
  ["sFameCheckerFlavorTextPointers[38]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡Seguiré entrenándome con KOGA,\\nmi maestro ninja!",
  ["sFameCheckerFlavorTextPointers[39]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003Mi padre es el LÍDER del GIMNASIO\\nde este pueblo.\\pYo me estoy entrenando para usar\\nPOKéMON del tipo VENENO igual\\lque hace mi padre.",
  ["sFameCheckerFlavorTextPointers[3]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según dicen, el PROF. OAK vive\\ncon su nieta DALIA y {RIVAL}.",
  ["sFameCheckerFlavorTextPointers[40]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, KOGA\\ntiene grandes conocimientos\\lde medicina.\\pIncluso elabora las medicinas\\nque sus POKéMON necesitan.",
  ["sFameCheckerFlavorTextPointers[41]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003La ZONA del SAFARI es gigante,\\n¿no te parece?\\pEl LÍDER del GIMNASIO de FUCSIA,\\nKOGA, viene con mucha frecuencia\\lpor aquí.\\pGracias a él, podemos jugar aquí\\nsin miedo.",
  ["sFameCheckerFlavorTextPointers[42]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003LÍDER del GIMNASIO POKéMON\\nde AZAFRÁN: SABRINA\\l¡Genio de los POKéMON PSÍQUICOS!",
  ["sFameCheckerFlavorTextPointers[43]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003¿Sabes algo de la LÍDER del\\nGIMNASIO de AZAFRÁN?\\pUsa POKéMON del tipo PSÍQUICO,\\n¿no?",
  ["sFameCheckerFlavorTextPointers[44]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡Tengo poderes psíquicos desde\\nque era niña!\\pPrimero aprendí a doblar cucharas\\ncon la mente.",
  ["sFameCheckerFlavorTextPointers[45]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡Odio luchar, pero si quieres\\npuedo enseñarte mis poderes!",
  ["sFameCheckerFlavorTextPointers[46]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, SABRINA\\nse comunica en combate con sus\\lPOKéMON, sin necesidad de hablar.",
  ["sFameCheckerFlavorTextPointers[47]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡SABRINA ganó al MAESTRO de\\nKARATE de la puerta de al lado!",
  ["sFameCheckerFlavorTextPointers[48]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003LÍDER del GIMNASIO POKéMON\\nde CANELA: BLAINE\\l¡El maestro de los acertijos!",
  ["sFameCheckerFlavorTextPointers[49]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003¡Mis feroces POKéMON de FUEGO\\nquemarán a quien me desafíe!",
  ["sFameCheckerFlavorTextPointers[4]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003He oído que OAK te tiene\\nmucha admiración, criatura.\\pEse carcamal era fuerte y guapote,\\npero ya hace mucho de eso.\\pHan pasado muchos años, sí.\\nEs la sombra de lo que fue.",
  ["sFameCheckerFlavorTextPointers[50]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003BLAINE se perdió en la montaña,\\ny se hizo de noche...\\p¡Pero apareció un feroz pájaro\\nPOKéMON...!\\p¡E iluminó el camino a BLAINE\\npara que pudiera bajar!",
  ["sFameCheckerFlavorTextPointers[51]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003BLAINE, del GIMNASIO CANELA,\\nes un hombre raro que lleva años\\lviviendo aquí.\\pAntes de que construyeran el\\nLABORATORIO, ya vivía aquí.",
  ["sFameCheckerFlavorTextPointers[52]"] = "\252\001\008\252\003\009¿Y esto?\\p\252\001\002\252\003\003Una foto de BLAINE\\ny el SR. FUJI...\\pAparecen juntos con una sonrisa\\nde oreja a oreja.",
  ["sFameCheckerFlavorTextPointers[53]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, BLAINE\\nsólo se quita las gafas de sol\\lcuando contesta a preguntas.",
  ["sFameCheckerFlavorTextPointers[54]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡Yo soy LORELEI, del ALTO MANDO!",
  ["sFameCheckerFlavorTextPointers[55]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡Nadie me supera con los POKéMON\\nque congelan!",
  ["sFameCheckerFlavorTextPointers[56]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003En esta isla nació y creció una\\nENTRENADORA fuerte y poderosa\\lcomo pocas.\\pSeguro que la conoces, se llama\\nLORELEI y es del ALTO MANDO.",
  ["sFameCheckerFlavorTextPointers[57]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Lo que sí se conoce de ella es\\nsu estilo de lucha elegante, único\\ly calculador.",
  ["sFameCheckerFlavorTextPointers[58]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¿Sabías que LORELEI tiene un\\nmontón de muñecos de peluche?\\p¡Cada vez que vuelve a ISLA\\nQUARTA, aumenta la colección!",
  ["sFameCheckerFlavorTextPointers[59]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003Creo que el LAPRAS que tiene,\\nes el mismo que atrapó de pequeña.\\pYo creo que se hizo con él\\nen la CUEVA GLACIADA...\\pMe parece que lo tiene desde\\nentonces.",
  ["sFameCheckerFlavorTextPointers[5]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003El PROF. OAK va a tener pronto\\nsu propio programa de radio.\\pSerá el SEMINARIO sobre POKéMON\\ndel PROF. OAK.",
  ["sFameCheckerFlavorTextPointers[60]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡Yo soy BRUNO, del ALTO MANDO!",
  ["sFameCheckerFlavorTextPointers[61]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡Siempre he vivido con mis POKéMON\\ndel tipo LUCHA y los he entrenado\\lyo mismo!",
  ["sFameCheckerFlavorTextPointers[62]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, BRUNO\\nse unió al ALTO MANDO para luchar\\lcontra los mejores ENTRENADORES.",
  ["sFameCheckerFlavorTextPointers[63]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003BRUNO, ejemplo al que sigo, viene\\nal BALNEARIO cada vez que puede.\\pNo sólo para recuperarse él,\\ntambién lo hace por sus POKéMON.",
  ["sFameCheckerFlavorTextPointers[64]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003Era uno de los miembros del ALTO\\nMANDO. Se llamaba BRUNO.\\pPero se fue decepcionado cuando\\nvio que no quedaban bastones de\\lcaramelo superfuertes.",
  ["sFameCheckerFlavorTextPointers[65]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Fíjate en BRUNO...\\nÉl se entrenó con un tal MARCIAL.",
  ["sFameCheckerFlavorTextPointers[66]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡Yo soy AGATHA, del ALTO MANDO!",
  ["sFameCheckerFlavorTextPointers[67]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003Los POKéMON del tipo FANTASMA\\nde AGATHA son escalofriantemente\\lfuertes.",
  ["sFameCheckerFlavorTextPointers[68]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Además ¡no sabes el genio que\\ntiene la señora!\\p¡Como empiece a gritar, lo llevas\\nclaro!",
  ["sFameCheckerFlavorTextPointers[69]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, AGATHA\\ny el PROF. OAK estuvieron\\penfrentados durante su formación\\ncomo ENTRENADORES.",
  ["sFameCheckerFlavorTextPointers[6]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Si le enseñas a DALIA tus POKéMON,\\nsabrá decirte si les gustas o no.\\pY puede que les dé un lavado de\\ncara para que estén presentables.",
  ["sFameCheckerFlavorTextPointers[70]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003He oído que OAK te tiene\\nmucha admiración, criatura.\\pEse carcamal era fuerte y guapote,\\npero ya hace mucho de eso.\\pHan pasado muchos años, sí.\\nEs la sombra de lo que fue.",
  ["sFameCheckerFlavorTextPointers[71]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003Mira a AGATHA, por ejemplo.\\pEs el miembro de más edad\\ndel ALTO MANDO.",
  ["sFameCheckerFlavorTextPointers[73]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003¡Los dragones son míticos POKéMON!\\p¡Son difíciles de capturar y\\nentrenar, pero sus poderes son\\lmuy superiores!\\p¡Son casi invencibles!",
  ["sFameCheckerFlavorTextPointers[74]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡Es justo!\\n¡Es admirado!\\l¡Todos quieren estar a su lado!",
  ["sFameCheckerFlavorTextPointers[75]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003Tenemos un cliente habitual, LANCE,\\nque suele comprar capas.\\pLa verdad es que debe de tener\\nun montón iguales en su casa...",
  ["sFameCheckerFlavorTextPointers[76]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según fuentes cercanas, quien fundó\\nel clan de los maestros del tipo\\lDRAGÓN fue el abuelo de LANCE.",
  ["sFameCheckerFlavorTextPointers[77]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Por lo que sé, un primo de LANCE\\nes también LÍDER de un GIMNASIO\\lde por ahí.",
  ["sFameCheckerFlavorTextPointers[78]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡Él fue también el que inventó el\\nSistema de Almacenamiento de\\lPOKéMON para PC!",
  ["sFameCheckerFlavorTextPointers[79]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003¡BILL tiene muchísimos POKéMON!\\n¡Y algunos son muy raros!",
  ["sFameCheckerFlavorTextPointers[7]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003Pero los POKéMON a quien más\\nquieren es a DALIA, creo.",
  ["sFameCheckerFlavorTextPointers[80]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡Es mi nieto!\\p¡Le gustaba coleccionar cosas\\ndesde niño!",
  ["sFameCheckerFlavorTextPointers[81]"] = "\252\001\008\252\003\009¿Qué POKéMON prefiere?\\p\252\006\004\252\001\002\252\003\003BILL es un POKéMANÍACO,\\na él le gustan todos.\\pCreo que el primero que atrapó\\nfue un ABRA.",
  ["sFameCheckerFlavorTextPointers[82]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003BILL es de CIUDAD TRIGAL,\\ndonde aún viven sus amigos.\\pDicen que es una ciudad muy\\nalegre y animada.",
  ["sFameCheckerFlavorTextPointers[83]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Creo que BILL no tolera muy bien\\nla leche. Le da dolor de estómago.",
  ["sFameCheckerFlavorTextPointers[84]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\005\252\001\002\252\003\003¡Es muy amable!\\p¡Cuida de los POKéMON huérfanos\\ny abandonados!",
  ["sFameCheckerFlavorTextPointers[85]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003El tipo, que ya tiene unos años,\\nse plantó en nuestra GUARIDA.\\pY empezó a decir que estábamos\\nhaciendo daño a los POKéMON.\\p¡La cosa es para tomársela\\nen serio!",
  ["sFameCheckerFlavorTextPointers[86]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003REVISTA POKéMON\\n¡Gran concurso mensual de dibujo\\lPOKéMON!\\pEl formulario de inscripción está\\nen...\\p¡Anda, se lo han llevado!\\n¡Se ha debido de inscribir alguien!",
  ["sFameCheckerFlavorTextPointers[87]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003He oído que el SR. FUJI tampoco\\nes de por aquí.",
  ["sFameCheckerFlavorTextPointers[88]"] = "\252\001\008\252\003\009¿Y esto?\\p\252\001\002\252\003\003Una foto de BLAINE\\ny el SR. FUJI...\\pAparecen juntos con una sonrisa\\nde oreja a oreja.",
  ["sFameCheckerFlavorTextPointers[89]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Nota del editor: el tímido\\nSR. FUJI no ha querido contestar\\la nuestras preguntas.\\pCon todo, hay que decir que es una\\npersona muy querida en PUEBLO\\lLAVANDA.",
  ["sFameCheckerFlavorTextPointers[8]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003La chiquilla cuidaba con mimo a un\\nPOKéMON. Era un angelito, la cría.\\pLo que no recuerdo es el nombre...\\nBueno, creo que era DALIA.",
  ["sFameCheckerFlavorTextPointers[90]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡El TEAM ROCKET necesita los\\nPOKéMON para financiar sus\\lmalvados planes!\\p¡Yo soy GIOVANNI, su líder!",
  ["sFameCheckerFlavorTextPointers[91]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Los tipejos esos que se apoderaron\\nde nuestro edificio...\\pSu JEFE dijo que estaba buscando\\nPOKéMON fuertes.",
  ["sFameCheckerFlavorTextPointers[92]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡El JEFE del TEAM ROCKET es muy\\ncruel!\\pSólo quiere a los POKéMON para\\nluchar.",
  ["sFameCheckerFlavorTextPointers[93]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¡Ésta es mi guarida!\\p¡Quería volver a formar al TEAM\\nROCKET desde aquí!",
  ["sFameCheckerFlavorTextPointers[94]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003¿Qué dices? ¿Que GIOVANNI era\\nel LÍDER del GIMNASIO?",
  ["sFameCheckerFlavorTextPointers[95]"] = "\252\001\008\252\003\009¿Qué ha dicho esta persona?\\p\252\006\004\252\001\002\252\003\003Tú... tú no eres el retoño\\nde GIOVANNI, ¿verdad?\\pNo, no puede ser, el retoño\\nde GIOVANNI es pelirrojo.",
  ["sFameCheckerFlavorTextPointers[9]"] = "\252\001\008\252\003\009¿Qué ponía aquí?\\p\252\001\002\252\003\003Según dicen, el PROF. OAK vive\\ncon su nieta DALIA y {RIVAL}.",
  ["sFameCheckerNameAndQuotesPointers[14]"] = "\252\001\008\252\003\009SR. FUJI",
  ["sFameCheckerNameAndQuotesPointers[16]"] = "\252\001\008\252\003\009Comentario del PROF. OAK\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003¿Sabes por qué luchan y compiten\\ntanto por ti los POKéMON?\\pPorque ven el cariño que tienes\\nhacia los POKéMON y lo que confías\\len ellos.\\pTenlo siempre en cuenta.",
  ["sFameCheckerNameAndQuotesPointers[17]"] = "\252\001\008\252\003\009Comentario de DALIA para {PLAYER}:\\p\252\006\005\252\001\002\252\003\003Mientras hacía una pausa para\\ntomar té, he visto que te has\\lvuelto muy fuerte y hábil.\\pEspero que sigas siendo la persona\\nideal para luchar contra mi\\lhermano pequeño.",
  ["sFameCheckerNameAndQuotesPointers[18]"] = "\252\001\008\252\003\009Comentario de BROCK para {PLAYER}:\\p\252\006\004\252\001\002\252\003\003En este mundo nuestro tan grande,\\nhacen falta fuertes ENTRENADORES.\\p¡Debemos seguir entrenándonos\\npara ser cada vez más fuertes!",
  ["sFameCheckerNameAndQuotesPointers[19]"] = "\252\001\008\252\003\009Comentario de MISTY para {PLAYER}:\\p\252\006\005\252\001\002\252\003\003Voy a seguir entrenándome aquí\\nen el GIMNASIO.\\pCuando perfeccione mi técnica,\\nme iré a viajar por ahí.",
  ["sFameCheckerNameAndQuotesPointers[1]"] = "\252\001\008\252\003\009DALIA",
  ["sFameCheckerNameAndQuotesPointers[20]"] = "\252\001\008\252\003\009Comentario de LT. SURGE\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003¡Eh, personaje!\\n¡Me quedé molido tras el combate!\\pNo pensé que hubiera ENTRENADORES\\ntan valientes como tú.\\pConseguiste que cambiara mi opinión\\nsobre ti.",
  ["sFameCheckerNameAndQuotesPointers[21]"] = "\252\001\008\252\003\009Comentario de ERIKA\\npara {PLAYER}:\\p\252\006\005\252\001\002\252\003\003Estoy encantada de que haya\\nENTRENADORES fuertes como tú.\\pMe motiva y me ayuda a superarme\\na mí misma.\\pEspero verte de nuevo.\\nZzz...",
  ["sFameCheckerNameAndQuotesPointers[22]"] = "\252\001\008\252\003\009Comentario de KOGA\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003Tú y yo deberíamos exigirnos\\nmás y entrenarnos con empeño para\\lcumplir lo que nos propongamos.\\pBueno, voy a entrenar a mi hija.",
  ["sFameCheckerNameAndQuotesPointers[23]"] = "\252\001\008\252\003\009Comentario de SABRINA\\npara {PLAYER}:\\p\252\006\005\252\001\002\252\003\003El cariño que les tienes a tus\\nPOKéMON...\\pTuvo más fuerza que mis poderes\\npsíquicos.",
  ["sFameCheckerNameAndQuotesPointers[24]"] = "\252\001\008\252\003\009Comentario de BLAINE\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003¡Mis POKéMON de fuego van\\na alcanzar una fuerza increíble!\\pA ver, una pregunta: ¿cuántos\\nPOKéMON del tipo FUEGO hay?",
  ["sFameCheckerNameAndQuotesPointers[25]"] = "\252\001\008\252\003\009Comentario de LORELEI\\npara {PLAYER}:\\p\252\006\005\252\001\002\252\003\003Estoy muy agradecida por tu ayuda.\\p¡Pero no te confíes, en combate\\nno pienso pasarte ni una!",
  ["sFameCheckerNameAndQuotesPointers[26]"] = "\252\001\008\252\003\009Comentario de BRUNO\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003He aprendido mucho de la fuerza\\nque tenéis tú y tus POKéMON...\\p¡La próxima vez seré yo quien\\nte enseñe a ti!",
  ["sFameCheckerNameAndQuotesPointers[27]"] = "\252\001\008\252\003\009Comentario de AGATHA\\npara {PLAYER}:\\p\252\006\005\252\001\002\252\003\003Espero que no te vuelvas como\\nel blandengue de OAK con los años.\\p¡Sigue mi ejemplo y no dejes\\nde luchar!",
  ["sFameCheckerNameAndQuotesPointers[28]"] = "\252\001\008\252\003\009Comentario de LANCE\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003Me estoy planteando\\nvolver a mi lugar de origen.\\pQuiero entrenar de nuevo a mis\\nPOKéMON y fortalecerlos un poco.\\pEspero verte por allí algún día\\nde estos.",
  ["sFameCheckerNameAndQuotesPointers[29]"] = "\252\001\008\252\003\009Comentario de BILL\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003¡Eh, oye! ¡CELIO no hace más\\nque hablar de ti, te pone por\\llas nubes!\\p¡Da gusto oírle!\\p¡Oye, si atrapas POKéMON raros,\\nven a verme! ¡Hasta lueguito!",
  ["sFameCheckerNameAndQuotesPointers[30]"] = "\252\001\008\252\003\009Comentario del SR. FUJI\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003Espero que no pienses sólo\\nen el bienestar de tus POKéMON...\\pConfío en que te preocupes por\\ntodos los POKéMON que hay...",
  ["sFameCheckerNameAndQuotesPointers[31]"] = "\252\001\008\252\003\009Comentario de GIOVANNI\\npara {PLAYER}:\\p\252\006\004\252\001\002\252\003\003En realidad, no quiero decirte\\nnada.\\pYo voy a concentrarme en mejorar\\ny punto.",
